// Enrich and Qualify Lead, base step 1: the client's People and Companies tables, resolved by the registry's
// table ids (Clients.ClayrootsPeopleTableID fldAkkVBD6fLBA9my and Clients.ClayrootsCompaniesTableID
// fldHhhOlD6RSzYi3p, passed by the caller as clayroots_people_table / clayroots_companies_table), looked up in
// the base meta for their field spellings, and the one People search that covers the whole resolve order at
// once. Never by table name: a client's People table is whatever the registry says it is (Adelante's is
// "USA DTC - Contacts"). Nothing here throws: an intake must never crash on a base that is off the standard;
// it reports `ready: false` with the reason and the run keeps today's DiscoLike path.
//
// Resolve order (Operator ruling 2026-09-02), the replier against the People table:
//   1. Final Email equals the reply email     2. Email equals it (both sides lowercased)
//   3. Contact Key equals first+last+the email's domain, built the way Waterfall Contacts Batch builds it
//   4. LinkedIn URL equals the lead's (lowercased, trailing slash stripped): the Alta reply without an email
// The formula ORs the keys so one call fetches every candidate; Pick Person applies the precedence.
const lead = $('Lead In').first().json || {};
const s = (v) => String(v == null ? '' : v).trim();
const base = s(lead.clayroots_base);
const peopleId = s(lead.clayroots_people_table);
const companiesId = s(lead.clayroots_companies_table);
const email = s(lead.lead_email).toLowerCase();
const emailDomain = email.includes('@') ? email.split('@')[1] : '';
const linkedinKey = s(lead.linkedin_url).toLowerCase().replace(/\/+$/, '');
const r = $input.first().json || {};
const body = (r.body !== undefined) ? r.body : r;
const tables = (body && Array.isArray(body.tables)) ? body.tables : null;

const out = { base, email, emailDomain, contactKey: '', linkedinKey, ready: false, reason: '', peopleTableId: '', peopleTableName: '', companiesTableId: '', companiesTableName: '', peopleFields: {}, companiesFields: {}, matchOrder: [], peopleUrl: '' };
if (!peopleId) { out.reason = 'client registry has no ClayrootsPeopleTableID'; return [{ json: out }]; }
if (!companiesId) { out.reason = 'client registry has no ClayrootsCompaniesTableID'; return [{ json: out }]; }
if (!tables) { out.reason = 'could not read the table list for base ' + base + ': ' + JSON.stringify(body).slice(0, 160); return [{ json: out }]; }

const byId = (id) => tables.find((x) => String(x.id || '') === id);
const people = byId(peopleId);
const companies = byId(companiesId);
if (!people) { out.reason = 'registry People table ' + peopleId + ' is not in base ' + base; return [{ json: out }]; }
if (!companies) { out.reason = 'registry Companies table ' + companiesId + ' is not in base ' + base; return [{ json: out }]; }

// Field names as the base actually spells them (case-insensitive), so a formula never names a missing column (422).
const actual = (t, wanted) => { const f = (t.fields || []).find((x) => String(x.name || '').trim().toLowerCase() === wanted.toLowerCase()); return f ? f.name : ''; };
const PEOPLE_KEYS = ['Name', 'first_name', 'last_name', 'Title', 'Seniority', 'Department', 'Email', 'Final Email', 'Contact Key', 'LinkedIn URL', 'Phone', 'Domain', 'Company', 'Companies', 'Tag', 'Signals', 'Signal At', 'Campaigns', 'Status', 'Description', 'Industry Groups', 'Employees', 'Revenue Range', 'Country', 'State', 'City', 'Social URLs', 'Phones'];
const COMPANY_KEYS = ['Domain', 'Company', 'Description', 'Industry Groups', 'Employees', 'Revenue Range', 'Country', 'State', 'City', 'Tag', 'Signals', 'Signal At', 'Campaigns', 'Social URLs', 'Phones', 'Business Model', 'Keywords'];
for (const k of PEOPLE_KEYS) { const a = actual(people, k); if (a) out.peopleFields[k] = a; }
for (const k of COMPANY_KEYS) { const a = actual(companies, k); if (a) out.companiesFields[k] = a; }
out.peopleTableId = people.id; out.peopleTableName = people.name;
out.companiesTableId = companies.id; out.companiesTableName = companies.name;

// Contact Key, the Waterfall Contacts Batch recipe: cleaned first + cleaned last, lowercased, + domain, no separators.
const cleanFirst = (f) => { if (!f) return ''; let n = String(f).split(',')[0].trim().split(/\s+/)[0] || ''; return n.replace(/[^A-Za-z\-']/g, ''); };
const cleanLast = (f) => { if (!f) return ''; return String(f).split(',')[0].trim().split(/\s+/).join(' ').replace(/[^A-Za-z\-'\s]/g, '').trim(); };
const first = cleanFirst(lead.first_name), last = cleanLast(lead.last_name);
if (first && emailDomain) out.contactKey = (first.toLowerCase() + last.toLowerCase() + emailDomain).trim();

const q = (v) => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const parts = [];
if (email && out.peopleFields['Final Email']) { parts.push('LOWER({' + out.peopleFields['Final Email'] + '}) = ' + q(email)); out.matchOrder.push('Final Email'); }
if (email && out.peopleFields['Email']) { parts.push('LOWER({' + out.peopleFields['Email'] + '}) = ' + q(email)); out.matchOrder.push('Email'); }
if (out.contactKey && out.peopleFields['Contact Key']) { parts.push('LOWER({' + out.peopleFields['Contact Key'] + '}) = ' + q(out.contactKey)); out.matchOrder.push('Contact Key'); }
if (linkedinKey && out.peopleFields['LinkedIn URL']) { parts.push('LOWER(REGEX_REPLACE({' + out.peopleFields['LinkedIn URL'] + '} & "", "/+$", "")) = ' + q(linkedinKey)); out.matchOrder.push('LinkedIn URL'); }
if (!parts.length) { out.reason = 'People table ' + people.name + ' carries none of Final Email / Email / Contact Key / LinkedIn URL, or the lead has neither an email nor a LinkedIn URL'; return [{ json: out }]; }
const formula = parts.length === 1 ? parts[0] : 'OR(' + parts.join(', ') + ')';
out.peopleUrl = 'https://api.airtable.com/v0/' + base + '/' + people.id + '?maxRecords=10&filterByFormula=' + encodeURIComponent(formula);
out.ready = true;
return [{ json: out }];

// Enrich and Qualify Lead, base step 2: the one People row that is the replier, by the resolve order
// (Final Email, then Email, then Contact Key, then LinkedIn URL), out of the candidates the single search returned.
// Also plans the Companies read: the row's Companies link when it has one, else the row's Domain, so the
// company facts come from the base and never from a paid call. Not found = `person_found: false`, and the
// run keeps today's DiscoLike path.
const cfg = $('Resolve Base Tables').first().json || {};
const r = $input.first().json || {};
const body = (r.body !== undefined) ? r.body : r;
const records = (body && Array.isArray(body.records)) ? body.records : [];
const pf = cfg.peopleFields || {};
const lower = (v) => String(v == null ? '' : (Array.isArray(v) ? v[0] : v)).trim().toLowerCase();
const fieldOf = (rec, key) => { const f = (rec && rec.fields) || {}; const a = pf[key]; return a ? f[a] : undefined; };

let hit = null, match = '';
const email = cfg.email || '', key = cfg.contactKey || '';
if (email && pf['Final Email']) { hit = records.find((x) => lower(fieldOf(x, 'Final Email')) === email) || null; if (hit) match = 'Final Email'; }
if (!hit && email && pf['Email']) { hit = records.find((x) => lower(fieldOf(x, 'Email')) === email) || null; if (hit) match = 'Email'; }
if (!hit && key && pf['Contact Key']) { hit = records.find((x) => lower(fieldOf(x, 'Contact Key')) === key) || null; if (hit) match = 'Contact Key'; }
const li = cfg.linkedinKey || '';
if (!hit && li && pf['LinkedIn URL']) { hit = records.find((x) => lower(fieldOf(x, 'LinkedIn URL')).replace(/\/+$/, '') === li) || null; if (hit) match = 'LinkedIn URL'; }

const out = Object.assign({}, cfg, { person_found: !!hit, base_match: match, personRecordId: hit ? hit.id : '', personFields: hit ? (hit.fields || {}) : {}, companyLinkId: '', companyUrl: '', candidates: records.length, reason: '' });
if (!hit) {
  out.reason = records.length ? (records.length + ' candidate row(s) but none matched the resolve order') : (body && body.error ? 'People search failed: ' + JSON.stringify(body.error).slice(0, 160) : 'no People row matched ' + [email, key, li].filter(Boolean).join(' / '));
  return [{ json: out }];
}

const links = fieldOf(hit, 'Companies');
if (Array.isArray(links) && links.length) out.companyLinkId = String(links[0] && links[0].id ? links[0].id : links[0]);
const q = (v) => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
let formula = 'FALSE()';
const cf = cfg.companiesFields || {};
if (out.companyLinkId) formula = 'RECORD_ID() = ' + q(out.companyLinkId);
else if (cf['Domain']) { const d = lower(fieldOf(hit, 'Domain')) || cfg.emailDomain || ''; if (d) formula = 'LOWER({' + cf['Domain'] + '}) = ' + q(d); }
out.companyUrl = 'https://api.airtable.com/v0/' + cfg.base + '/' + cfg.companiesTableId + '?maxRecords=1&filterByFormula=' + encodeURIComponent(formula);
return [{ json: out }];

// Enrich and Qualify Lead, base step 3: the person facts from the People row and the company facts from its
// Companies row (the People lookups when the link is missing), and a bizdata object in the DiscoLike shape
// (name, domain, description, industry_groups, employees, revenue_range, address, social_urls, phones), so
// Build Prompt, the callers' Prospects writes and the Slack cards read the same keys whichever source filled them.
const pick = $('Pick Person').first().json || {};
const r = $input.first().json || {};
const body = (r.body !== undefined) ? r.body : r;
const crec = (body && Array.isArray(body.records) && body.records.length) ? body.records[0] : null;
const pf = pick.peopleFields || {}, cf = pick.companiesFields || {};
const P = pick.personFields || {}, C = (crec && crec.fields) || {};
const one = (v) => { if (v == null) return ''; if (Array.isArray(v)) return v.length ? String(v[0] == null ? '' : (v[0] && v[0].name ? v[0].name : v[0])).trim() : ''; if (typeof v === 'object') return String(v.name || v.value || '').trim(); return String(v).trim(); };
const all = (v) => { if (v == null) return []; if (!Array.isArray(v)) return one(v) ? [one(v)] : []; return v.map((x) => (x && typeof x === 'object') ? String(x.id || x.name || '') : String(x)).filter(Boolean); };
const person = (k) => (pf[k] ? P[pf[k]] : undefined);
const company = (k) => { const a = cf[k]; if (a && C[a] != null) return C[a]; return person(k); };
const list = (v) => String(v == null ? '' : v).split(/,\s*/).map((x) => x.trim()).filter(Boolean);

const personOut = {
  record_id: pick.personRecordId || '', name: one(person('Name')),
  title: one(person('Title')), seniority: one(person('Seniority')), department: one(person('Department')),
  linkedin_url: one(person('LinkedIn URL')), phone: one(person('Phone')),
  email: one(person('Email')), final_email: one(person('Final Email')), status: one(person('Status')),
  domain: one(person('Domain')), company: one(person('Company')), tag: one(person('Tag')),
  signals: all(person('Signals')), signal_at: one(person('Signal At')), campaigns: all(person('Campaigns'))
};
const companyOut = {
  record_id: crec ? crec.id : '', domain: one(company('Domain')), company: one(company('Company')),
  description: one(company('Description')), industry_groups: one(company('Industry Groups')),
  employees: one(company('Employees')), revenue_range: one(company('Revenue Range')),
  country: one(company('Country')), state: one(company('State')), city: one(company('City')),
  tag: one(company('Tag')), signals: all(company('Signals')), signal_at: one(company('Signal At')), campaigns: all(company('Campaigns')),
  social_urls: list(one(company('Social URLs'))), phones: list(one(company('Phones')))
};
const bizdata = {
  name: companyOut.company, domain: companyOut.domain, description: companyOut.description,
  industry_groups: companyOut.industry_groups, employees: companyOut.employees, revenue_range: companyOut.revenue_range,
  address: { country: companyOut.country, state: companyOut.state, city: companyOut.city },
  social_urls: companyOut.social_urls, phones: companyOut.phones,
  _source: 'client base' + (crec ? ' (Companies row ' + crec.id + ')' : ' (People lookups, no Companies row)')
};
return [{ json: {
  base_found: true, base_match: pick.base_match || '', base_source: "From the client's People table",
  base_people_record_id: pick.personRecordId || '', base_company_record_id: crec ? crec.id : '',
  base_people_table_id: pick.peopleTableId || '', base_companies_table_id: pick.companiesTableId || '',
  person: personOut, company: companyOut, bizdata
} }];

// Enrich and Qualify Lead, step 1: the one copy of the qualification prompt.
// Passthrough helper on the Clean Fields model: one item in, one item out, no run-log row of its own;
// the caller's row carries the outcome. Callers: Handle New Lead from PlusVibe, Handle New Lead from Alta,
// Handle New Booking. The helper reads the rubric, reads what the client's base already holds about the
// replier (ruling 2026-09-02: the intake reads before it pays), enriches live only when the base has no row,
// judges and hands the verdict back. It writes nothing: the caller stamps its own CRM row with the field
// names it always used.
//
// INPUT CONTRACT, the passthrough item (field: who supplies it):
//   client_name             required. The Clients row's Client name; resolves the KB qualification-prompt row.
//                           PlusVibe/Alta: Client Vars.clientName. Booking: Resolve Client.clientName.
//   clayroots_base          the Clients row's Clayroots Base ID ('' when the client has none). With a lead_email or a
//                           linkedin_url it opens the base read: People by Final Email, then Email, then Contact Key,
//                           then LinkedIn URL; the row's Companies link for the company facts. PlusVibe: Client Vars.clayrootsBase.
//                           Alta: Get Client Row 'Clayroots Base ID'. Booking: Resolve Client.clayrootsBase.
//   clayroots_people_table, clayroots_companies_table
//                           the Clients row's ClayrootsPeopleTableID (fldAkkVBD6fLBA9my) and ClayrootsCompaniesTableID
//                           (fldHhhOlD6RSzYi3p), '' when unset. The base read resolves both tables by these ids, never
//                           by name; without both it skips the base and goes to DiscoLike, with the reason on base_reason.
//                           PlusVibe: Find Client Row. Alta: Get Client Row. Booking: Resolve Client.clayrootsPeopleTable /
//                           clayrootsCompaniesTable.
//   system_prompt_fallback  optional. Rubric used when the KB has no row for the client. PlusVibe/Alta pass the
//                           legacy Clients field 'Qualification Prompt'. Empty too: a generic one-line rubric.
//   first_name, last_name, job_title, company_name, lead_email, linkedin_url
//                           the lead as the caller normalized it (Normalize / Alta Normalize / Normalize Booking + Attribution).
//   domain                  the company domain the caller resolved ('' when unknown).
//   enrich_domain           the domain DiscoLike is asked about; '' for freemail, then bizdata stays {}.
//   is_freemail             boolean; drives the EMAIL TYPE line.
//   city, state, country_code
//                           optional; LOCATION is written only when one is present (the booking door has none).
//   source_line             optional; written as 'SOURCE: ...'. Alta: 'Alta (linkedin reply)'.
//   company_context         optional; a caller-formatted block with its own header, inserted verbatim.
//                           Alta: the enrichment fields Alta sent with the reply.
//   context                 required; the caller-formatted event block, inserted verbatim: what happened and the
//                           thread, history or booking notes the judge must read.
//                           PlusVibe: latest reply + recent exchange. Alta: latest reply. Booking: the booking,
//                           the attribution line, prior history on the prospect row, the booking notes.
//   situation_ask           optional; what situation_summary must state. Default: the reply wording below.
//                           Booking: 'what the booking signals and what they want from the call'.
// Everything else on the item rides through untouched.
//
// OUTPUT, added to the same item by Flatten Verdict: qualification_status (strong|medium|weak|out_of_icp|''),
// qualification_label (the CRM QualificationStatus value), verdict_label, verdict_line, verdict_reason, brief,
// brief_plain, brief_md (the brief ends with the source line: "From the client's People table" or "Not in the
// base, enriched live"), situation_summary, recommended_action, timezone, phone (the base's Phone when held,
// else the qualifier's), company_name (the qualifier's canonical name when it returns one, else the input, else
// the base's Company), job_title and linkedin_url (the input's, filled from the base when empty), bizdata (the
// DiscoLike shape: from the base when the row was found, else DiscoLike JSON, {} when none), kb_found,
// base_found, base_match (Final Email | Email | Contact Key), base_source, base_reason, base_person, base_company,
// base_people_record_id, base_company_record_id.

const lead = $('Lead In').first().json || {};
const s = (v) => String(v == null ? '' : v).trim();

// The rubric: the client's KB qualification-prompt row, else the caller's fallback, else a generic line.
let kb = '';
try { const r = $('Find Qual Prompt').first().json || {}; const f = r.fields || r; kb = String(f['Content'] || '').replace(/\\([_*[\]`#|>~-])/g, '$1').trim(); } catch (e) { kb = ''; }
const kbFound = !!kb;
const systemPrompt = kb || s(lead.system_prompt_fallback) || ('You qualify inbound leads for ' + (s(lead.client_name) || 'the client') + ', a B2B company. Decide whether the lead is a fit and return the structured JSON asked for.');

// What the base holds: Base Facts ran only when the People row was found (every other leg went to DiscoLike).
let base = null;
try { const b = $('Base Facts').first().json; if (b && b.base_found) base = b; } catch (e) { base = null; }
let baseReason = '';
if (!base) {
  if (!s(lead.clayroots_base)) baseReason = 'client has no Clayroots base on its registry row';
  else if (!s(lead.clayroots_people_table)) baseReason = 'client registry has no ClayrootsPeopleTableID';
  else if (!s(lead.clayroots_companies_table)) baseReason = 'client registry has no ClayrootsCompaniesTableID';
  else if (!s(lead.lead_email) && !s(lead.linkedin_url)) baseReason = 'no reply email or LinkedIn URL to resolve against the base';
  else {
    try { const t = $('Resolve Base Tables').first().json || {}; if (!t.ready) baseReason = t.reason || 'base tables not resolved'; } catch (e) { baseReason = 'base tables not read'; }
    if (!baseReason) { try { baseReason = ($('Pick Person').first().json || {}).reason || 'no People row matched'; } catch (e) { baseReason = 'no People row matched'; } }
  }
}
const person = base ? (base.person || {}) : {};
const company = base ? (base.company || {}) : {};

// Firmographics: the base's Companies row when the replier was found; else DiscoLike bizdata for the enrich
// domain; {} when there was no domain to ask about or nothing came back.
let biz = {};
if (base) biz = base.bizdata || {};
else if (s(lead.enrich_domain)) { try { const b = $('DiscoLike BizData').first().json; if (b && typeof b === 'object' && !Array.isArray(b)) biz = b; } catch (e) { biz = {}; } }

const jobTitle = s(lead.job_title) || s(person.title);
const linkedin = s(lead.linkedin_url) || s(person.linkedin_url);
const companyName = s(lead.company_name) || s(company.company) || s(person.company);
const name = (s(lead.first_name) + ' ' + s(lead.last_name)).trim() || s(person.name);
const contact = s(lead.lead_email) || linkedin;
const emailType = lead.is_freemail
  ? 'PERSONAL/FREEMAIL, the domain is the email provider, NOT the company; web-search the real company + phone'
  : (s(lead.lead_email) ? 'business domain' : 'no email, LinkedIn lead');
const location = [s(lead.city), s(lead.state), s(lead.country_code)].filter(Boolean).join(', ') || (base ? [s(company.city), s(company.state), s(company.country)].filter(Boolean).join(', ') : '');
const situationAsk = s(lead.situation_ask) || 'what the prospect signaled and what they want next, interpreting the latest reply in context of our last message. Resolve vague replies like "sure"/"yes"/"ok" into the actual thing they agreed to or asked for (e.g. "Said yes to a quick walkthrough video" or "Asked us to send more on how it works before a call")';

const head = ['LEAD: ' + [name, jobTitle || 'title unknown', companyName || s(lead.domain) || 'company unknown', contact].join(' | ')];
if (s(lead.source_line)) head.push('SOURCE: ' + s(lead.source_line));
head.push('EMAIL TYPE: ' + emailType);
if (location) head.push('LOCATION: ' + location);
head.push('DOMAIN: ' + (s(lead.domain) || s(company.domain)));
if (linkedin) head.push('LINKEDIN: ' + linkedin);

const parts = [head.join('\n')];
if (base) {
  const sigCount = Array.isArray(company.signals) ? company.signals.length : 0;
  const campCount = Array.isArray(person.campaigns) ? person.campaigns.length : 0;
  parts.push('PERSON (from the client\'s People table, matched on ' + (base.base_match || 'the base') + '; this is our own list data, trust it over guesses):\n' + [
    'title: ' + (s(person.title) || 'unknown'), 'seniority: ' + (s(person.seniority) || 'unknown'), 'department: ' + (s(person.department) || 'unknown'),
    'linkedin: ' + (s(person.linkedin_url) || 'none'), 'phone: ' + (s(person.phone) || 'none'),
    'email status: ' + (s(person.status) || 'unknown'), 'list tag: ' + (s(person.tag) || s(company.tag) || 'none'),
    'signals: ' + (sigCount ? sigCount + ' intent signal(s)' + (s(company.signal_at) ? ', latest ' + s(company.signal_at) : '') : 'none'),
    'campaigns: ' + (campCount ? campCount + ' campaign(s) on our side' : 'none recorded')
  ].join(' | '));
}
if (s(lead.company_context)) parts.push(s(lead.company_context));
parts.push((base ? 'COMPANY FIRMOGRAPHICS (from the client\'s Companies table):\n' : 'COMPANY FIRMOGRAPHICS (DiscoLike, empty/ignore for freemail):\n') + JSON.stringify(biz));
if (s(lead.context)) parts.push(s(lead.context));
parts.push('Run the qualification. Output structured JSON. "situation_summary": ONE plain-English line (max 140 chars) stating ' + situationAsk + '. "verdict_reason": ONE plain-English line (max 120 chars) stating why this lead is or is not a fit, citing the deciding factor. Never paste the raw reply or notes verbatim; no names, signatures, or URLs.');

return [{ json: {
  systemPrompt, kbFound, promptText: parts.join('\n\n'), bizdata: biz,
  baseFound: !!base, baseMatch: base ? (base.base_match || '') : '',
  baseSource: base ? "From the client's People table" : 'Not in the base, enriched live',
  baseReason, basePerson: person, baseCompany: company,
  basePeopleRecordId: base ? (base.base_people_record_id || '') : '', baseCompanyRecordId: base ? (base.base_company_record_id || '') : ''
}, pairedItem: { item: 0 } }];

// Enrich and Qualify Lead, step 2: the verdict, cleaned once, in one shape, merged onto the passthrough item.
// The label maps are the one copy of what every caller used to carry: qualification_label is the CRM
// QualificationStatus value, verdict_label the human line the briefs open with. brief_md is the
// Qualification Brief markdown (bold first line, bullets) the callers used to format themselves.
// The brief's last line names the source (ruling 2026-09-02): "From the client's People table" when the
// replier was resolved in the base, "Not in the base, enriched live" when DiscoLike ran.
const stripCite = (t) => String(t || '').replace(/[-]/g, '').replace(/cite(turn\d+\w+?\d+)+/gi, '').replace(/turn\d+(?:view|search|news|image|video|product|ref)\d+/gi, '').replace(/cite/gi, '').replace(/ {2,}/g, ' ').trim();
const stripEmoji = (t) => String(t || '').replace(/:[a-z0-9_+-]+:/gi, '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2190}-\u{21FF}\u{2300}-\u{23FF}\u{FE0F}\u{200D}]/gu, '').replace(/ {2,}/g, ' ').trim();
const s = (v) => String(v == null ? '' : v).trim();

const lead = $('Lead In').first().json || {};
const built = $('Build Prompt').first().json || {};
const q = ($input.first().json || {}).output || {};
const person = built.basePerson || {};
const company = built.baseCompany || {};
const sourceLine = built.baseSource || 'Not in the base, enriched live';

const status = String(q.qualification_status || '');
const qualificationLabel = ({ strong: 'Qualified', medium: 'Needs Review', weak: 'Needs Review', out_of_icp: 'Disqualified' })[status] || 'Needs Review';
const verdictLabel = ({ strong: 'Qualified', medium: 'Qualified (medium confidence)', weak: 'Qualified (weak fit)', out_of_icp: 'Not qualified' })[status] || 'Needs review';
const verdictReason = stripEmoji(stripCite(q.verdict_reason || '')).slice(0, 200);
const verdictLine = verdictLabel + ': ' + (verdictReason || 'see brief');
const briefBody = stripCite(q.slack_brief_markdown || '').slice(0, 2700);
const brief = (briefBody ? briefBody + '\n' : '') + sourceLine;
const briefPlain = (verdictLine + '\n\n' + stripEmoji(brief)).slice(0, 2800);
const briefLines = briefPlain.split('\n').map((x) => x.trim()).filter(Boolean);
const briefMd = briefLines.length ? ['**' + briefLines[0] + '**', ''].concat(briefLines.slice(1).map((l) => '- ' + l)).join('\n') : '';
const qualifierPhone = stripCite(q.phone || '').replace(/[^\d+]/g, '').trim();
const phone = s(person.phone) || qualifierPhone;

return [{ json: Object.assign({}, lead, {
  qualification_status: status,
